function addAbortListener (signal, listener) {
  // The native helper accepts any signal-like EventTarget, so it also covers
  // cross-realm AbortSignal instances that fail an `instanceof` check.
  if (typeof signal.addEventListener === 'function') {
    const disposable = addAbortListenerNative(signal, listener)
    return () => disposable[Symbol.dispose]()
  }

  // Legacy support for an EventEmitter emitting an 'abort' event.
  signal.once('abort', listener)
  return () => signal.removeListener('abort', listener)
}

